  {kind='flowers',rows={' *   * ','\\|/ \\|/',' | * | ','  \\|/  '},colour='bloom'},
  {kind='rocks',rows={'  .--. ',' /    \\','(_____)',' ,  ,  '},colour='stone'},
  {kind='wheat',rows={' \\|/ \\|','  || ||',' \\|/ ||','  || ||'},colour='harvest'},
