    local room=#rooms>0 and rooms[((job and job.target or i)-1)%#rooms+1] or nil
    if i==1 and state.mode=="tool" then
      for _,r in ipairs(rooms) do if world:construction(r.index)<1 then room=r end end
    end
    if quiet and room then
      local at=anchor(room,i)
      resident={x=at.x,y=at.y,stage=job and 'working' or 'resting',mark=job and glyph(job.kind) or '~',walking=false}
    end
    if room or resident then
    local x,y=0,math.min(h-1,3+i)
    if room then x=room.x+2+((i-1)%math.max(1,room.w-4)); y=room.y+2+((i-1)//math.max(1,room.w-4))%(room.h-3) end
    if room and state.mode=="tool" and not resident then
      local travel=math.floor(phase*2+i)%math.max(2,(room.w-4)*2)
      x=room.x+2+math.min(travel,math.max(0,(room.w-4)*2-travel-1))
      x=math.min(room.x+room.w-3,x)
    end
    if resident then x,y=resident.x,resident.y end
    local col=d.mood=="inspired" and "violet" or (d.mood=="strained" and "amber" or "neutral")
    put(x,y,d.role=="founder" and "@" or "d",col,0)
    local mark=job and glyph(job.kind) or "~"
    if state.mode=="thinking" and d.role=="founder" then mark="?" end
    if state.mode=="idle" and (tonumber(state.age) or 0)>60 then mark="z" end
    if state.mode=="tool" then mark=math.floor(phase*3+i)%2==0 and "*" or "+" end
    if resident then
      mark=resident.mark
      if job and not resident.walking and resident.stage~='resting' then mark=glyph(job.kind) end
      if life.phase=='Night' and resident.stage=='resting' then col='violet' end
      if i==1 and layout.foot>=4 then text(w-strip,h-1,clip(d.name:match('^(%w+)')..': '..resident.stage,strip),strip,'neutral',0) end
    end
    put(x+1,y,mark,col,0)
    end
  end
  if life then
    if layout.foot>=4 then text(0,h-1,clip(quiet and 'Colony active' or 'D'..life.day..' '..life.phase..' '..life.weather,strip),strip,'green',0) end
    for _,g in ipairs(layout.gardens) do
      text(g.x,g.y-1,g.w>=6 and 'Garden' or 'Plot',g.w,'green',1)
      -- A cat paces the bank. Animals are scenery, never agent arrivals.
      local cat=math.floor(life.seconds/2+world.seed+g.side*5)%math.max(1,2*(g.w-1))
      cat=math.min(cat,2*(g.w-1)-cat)
      put(g.x+cat,g.y+g.h-1,'c','amber',1)
      if life.phase=='Dusk' or life.phase=='Night' then
        put(g.x+g.w-1,g.y+g.h-2,math.floor(life.seconds*3)%2==0 and '^' or '*','amber',0)
        put(g.x+g.w-1,g.y+g.h-3,"'",'wall',3)
      end
      for y=0,g.h-1 do
        for x=0,g.w-1 do
          local cell=g.side==0 and y*life.W+x+1 or (life.H-1-y)*life.W+life.W-x
          local alive=life.cells[cell]
          if alive then put(g.x+x,g.y+y,life.generation%3==0 and '"' or '*','bloom',2) end
        end
        local bend=math.floor((life.seconds+y+g.side)/3)%2
        put(g.x+g.w+1,g.y+y,bend==0 and '~' or '=','water',2)
      end
    end
    -- Sparse weather on the outside edge leaves doors and labels legible.
    if not quiet and not layout.compact and life.weather=='Rain' then
      for side=0,1 do for n=1,3 do
        local y=layout.top+(math.floor(life.seconds*5)+n*7)%math.max(1,layout.bottom-layout.top)
        put(side==0 and 0 or w-1,y,'/','water',3)
      end end
    elseif not quiet and not layout.compact and life.phase=='Night' then
      for side=0,1 do for n=1,2 do
        local x=(side==0 and 0 or w-strip)+(world.seed+n*7)%strip
        put(x,layout.top-1,'.','violet',3)
      end end
    end
  end
  for i,e in ipairs(world.incidents) do
    local x=w-strip+math.min(strip-1,2+i*2)
    local y=math.min(layout.bottom-1,layout.top+i)
    local ch,col="!","red"
    if e.kind=="caravan" then ch,col="*","green"; x=w-strip+1+math.floor(phase*2)%math.max(1,strip-2)
    elseif e.kind=="mandate" then ch,col="?","amber" end
    put(x,y,ch,col,0)
    if world.profile=="chaos" and e.kind=="ambush" then put(x+1,y,"!",col,0) end
  end
  for i,a in ipairs(world.artifacts) do
    if #rooms>0 then local r=rooms[(a.room-1)%#rooms+1]; put(r.x+1+(i%math.max(1,r.w-2)),r.y+r.h-2,"*","violet",1) end
  end
  if #rooms>0 then
    put(rooms[1].x+1,rooms[1].y+2,world.z>0 and ">" or "+","amber",1)
    for i,item in ipairs(world.items) do
      local r=rooms[(item.room-1)%#rooms+1]
      put(r.x+1+i%math.max(1,r.w-2),r.y+r.h-2,":","wall",4)
    end
  end
  if not quiet and not layout.compact and (world.cave_until>world.clock or state.mode=="compacting") then
    for x=0,strip-1 do put(x,layout.top+(x+math.floor(phase*4))%math.max(1,layout.bottom-layout.top),"'","amber",1) end
  end
  if state.mode=="error" and (tonumber(state.age) or 0)<3 then put(w-2,2,"!","red",0) end
  local floor_colour=({spring={0.16,0.23,0.19},summer={0.22,0.23,0.16},autumn={0.25,0.19,0.15},winter={0.17,0.21,0.27}})[season]
  local layers=layout.decoration or View.decorate(world,layout)
  for i,layer in ipairs(layers) do
    if i==5 and layout.landscape then
      View.landscape.render(layout.landscape,quiet and 0 or (life and life.seconds or phase),life and life.phase=='Night',function(x,y,ch,colour)
        put(x,y,ch,colour,3,1,true)
      end,function() return budget-drawn end)
    end
    for _,v in ipairs(layer) do
    if drawn>=budget then flush();return end
    put(v.x,v.y,v.ch,v.floor and floor_colour or v.c)
  end end
  flush()
end
return View

end)()
View.landscape = Landscape
View.studioview = Studioview
local M = (function()
-- Included after local Sim and View by bundle.py. Host API is optional in harness.
local M = {}
local world, projected, layout, saved, life, plaque=nil,nil,nil,nil,nil,nil
local W,H,SEED,T,elapsed,clock=0,0,0,0,0,0
local crew={}
local signature=""
function M.init(ctx)
  W,H,SEED=ctx.w,ctx.h,ctx.seed or 0
  world,projected,layout,saved,life=nil,nil,nil,nil,nil
  plaque=Plaque.new()
  T,elapsed,signature,clock,crew=0,0,"",0,{}
end
function M.resize(ctx)
  if W==0 and H==0 then M.init(ctx); return end
  W,H=ctx.w,ctx.h; layout=nil
end
function M.restore(record) saved=record end
function M.export()
  if not world then return nil end
  return {schema_version=Sim.VERSION,seq=world.seq,counter_digest=Sim.digest(world.counts),world_state=world:snapshot(),
    legends=(projected or world).legends,summary=world.summary,life=life and life:snapshot(),
    status={name=world.name,scene=layout and layout.scene,year=world.year,season=(layout and layout.season) or "spring",population=#world.dwarves,
      crew=world.crew,wealth=world.wealth,stress=(projected or world).stress,z=world.z,progression=world:progression(),
      life=life and {day=life.day,phase=life.phase,weather=life.weather,generation=life.generation},
      studio=layout and layout.scene=='studio' and {tier=layout.tier,points=Studioview.points(world.counts),floors=#layout.floors,
        now=math.floor(clock)} or nil}}
end
local function studio_layout(params,presentation)
  local tier=Studioview.tier(Studioview.points(world.counts))
  local key=table.concat({W,H,tier,tostring(params.glyphs),presentation,tostring(params.density)},":")
  if layout and layout.key==key and layout.scene=='studio' then return end
  layout=Studioview.layout(W,H,tier,params); layout.key=key; layout.scene='studio'; layout.presentation=presentation
end
function M.step(dt,state)
  local j=state.journey or {}
  local identity=tostring(j.repo or "fortress")..":"..tostring(j.session_id or SEED)..":"..tostring(j.epoch or "preview")..":2"
  if not world or world.identity~=identity then
    world=Sim.new(Sim.hash(identity),identity)
    if saved and saved.counter_digest and saved.world_state then
      local ok,restored=pcall(function()
        local candidate=Sim.restore(saved.world_state,identity)
        if candidate and Sim.digest(candidate.counts)==saved.counter_digest then candidate:advance(candidate.clock); return candidate end
      end)
      if ok and restored then world=restored end
    end
    life=Life.new(world.seed,(saved and saved.world_state and saved.world_state.identity==identity and saved.life) or nil)
    saved=nil; elapsed=0; layout=nil; projected=nil; signature=''; clock=0; crew={}
  end
  local params=state.params or {}
  local presentation=params.presentation or 'auto'
  local scene=params.scene=='settlement' and 'settlement' or 'studio'
  if layout and (layout.presentation~=presentation or layout.scene~=scene) then layout=nil end
  local speed=tonumber((state.mod or {}).speed) or 1
  local real_dt=speed>0 and math.max(0,math.min(1,dt/speed)) or 0
  plaque:step((state.params or {}).paused and 0 or real_dt,state)
  if params.paused then
    if scene=='studio' then studio_layout(params,presentation); return end
    if not projected then projected=Sim.restore(world:snapshot(),identity) end
    if not layout then layout=View.layout(world,W,H,state.params); layout.presentation=presentation; layout.scene=scene end
    layout.season=View.season(state.context_pct)
    return
  end
  if speed==0 then return end
  T=T+dt; elapsed=elapsed+real_dt
  if scene~='studio' then life:advance(real_dt) end
  world:configure(state.params)
  local recent=j.recent or {}
  local last_seq=tonumber(j.seq) or 0
  if j.schema_version==2 and last_seq>world.seq then
    local first=recent[1]
    if not first or (tonumber(first.seq) or 0)>world.seq+1 then
      world:reconcile(j)
    else
      for _,e in ipairs(recent) do
        if (tonumber(e.seq) or 0)>world.seq+1 then world:reconcile(j); break end
        world:push(e)
      end
      if world.seq<last_seq or Sim.digest(world.counts)~=j.counter_digest then world:reconcile(j) end
    end
    elapsed=0
  elseif not j.schema_version and world.seq==0 and (tonumber(j.tools) or 0)>0 then
    -- Old writers have aggregates only; never interpret their unsequenced ring as history.
    local totals={}; for k,v in pairs(j) do totals[k]=v end
    totals.seq=1; totals.tick=0; world:reconcile(totals)
  end
  world:observe(state)
  if scene=='studio' then
    studio_layout(params,presentation)
    local target=j.schema_version==2 and (tonumber(j.tick) or 0)+math.floor(math.max(0,tonumber(state.age) or 0)*4)
      or world.clock+math.floor(elapsed*4)
